    index = 3
    for _ in range(m):
        t = int(data[index])
        p = float(data[index + 1])
        d = int(data[index + 2])
        tricks.append((t, p, d))
        index += 3

    result = expected_time_to_set_record(n, r, tricks)
    print(f"{result:.6f}")

